public boolean acquireRateLimit(JedisPool jedisPool, String userId, int maxRequests, int windowSeconds) {
    String luaScript = 
        "local current = redis.call('get', KEYS[1]) " +
        "if current and tonumber(current) >= tonumber(ARGV[1]) then " +
        "    return 0 " +
        "end " +
        "redis.call('incr', KEYS[1]) " +
        "if not current then " +
        "    redis.call('expire', KEYS[1], ARGV[2]) " +
        "end " +
        "return 1";

    String key = "rate_limit:" + userId;
    try (Jedis jedis = jedisPool.getResource()) {
        Object result = jedis.eval(luaScript, Collections.singletonList(key), Arrays.asList(String.valueOf(maxRequests), String.valueOf(windowSeconds)));
        return Long.valueOf(1L).equals(result);
    }
}
